import React from 'react';
import styles from './LoginScreen.module.css';
import Button from '../../ui/Button/Button';
// CORREÇÃO: Importa a imagem localmente
import logoImage from '../../../assets/images/logo.png'; 

const LoginScreen = ({ loginAs }) => {
  return (
    <div className={styles.container}>
      <div className={styles.logoContainer}>
        {/* CORREÇÃO: Usa a variável da imagem importada */}
        <img src={logoImage} alt="Selo Cidadania Logo" className={styles.logo} />
        <h1 className={styles.title}>Selo Cidadania</h1>
        <p className={styles.subtitle}>tagline</p>
      </div>
      <div className={styles.card}>
        <h2 className={styles.cardTitle}>Selecione um perfil para visualizar:</h2>
        <div className={styles.buttonGroup}>
          <Button onClick={() => loginAs('admin5')} variant="admin5">Admin Nível 5</Button>
          <Button onClick={() => loginAs('admin1')} variant="admin1">Admin Nível 1</Button>
          <Button onClick={() => loginAs('ong')} variant="ong">ONG</Button>
          <Button onClick={() => loginAs('user')} variant="user">Usuário</Button>
        </div>
      </div>
    </div>
  );
};
export default LoginScreen;
